window.RP_SESSION={"id":"S-58226458eed7","messages":[{"id":"RP-III-0122450","time":"2026-07-20T16:28:00+09:00","room":"RP III","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"길드를 서성거리는 위크. 새로운 환경을 탐색하는 모습에는 어울리지 않는 걸음걸이로 성큼성큼 돌아다닌다.\n\n훈련장에서 단련하는 사람들, 바삐 제 할 일을 하는 사람들... 그 사이에서 그는 자신의 자리를 찾았다. 의자를 하나 들고 나온 그는 마당 한가운데 의자를 놓고는 앉는다.\n\n그리고 연주는 예고도 없이 시작되었다.","characters":["P-d129df648db5"]},{"id":"RP-III-0122451","time":"2026-07-20T16:29:00+09:00","room":"RP III","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"https://youtu.be/UWnE9sCJEgw?si=XZEvfA7nvigItPH3","characters":["P-d129df648db5"]},{"id":"RP-III-0122452","time":"2026-07-20T16:38:00+09:00","room":"RP III","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"가사는 난해해서 알아듣기 어려웠지만, 음악은 가사로써 전해지는 것이 아니다.","characters":["P-d129df648db5"]},{"id":"RP-III-0122453","time":"2026-07-20T16:38:00+09:00","room":"RP III","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-d129df648db5"]},{"id":"RP-III-0122454","time":"2026-07-20T16:38:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'티아멧'의 매력 판정 :\n[4] + [-1] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0122455","time":"2026-07-20T16:53:00+09:00","room":"RP III","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-d129df648db5"]},{"id":"RP-III-0122456","time":"2026-07-20T16:54:00+09:00","room":"RP III","name":"위크","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d129df648db5"]},{"id":"RP-III-0122457","time":"2026-07-20T16:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
